import app.vera.coach.visionbeta.SportMath24;
class SportMathTest24 {
 static void check(boolean condition,String reason){if(!condition)throw new AssertionError(reason);}
 public static void main(String[] args){SportMath24 m=new SportMath24();check(m.add(40,-3,5,10000,10000,"cycling"),"first fix anchor");check(m.meters==0,"anchor is not distance");check(m.add(40.0001,-3,5,12000,12000,"cycling"),"valid 11m move");double distance=m.meters;check(distance>10&&distance<12,"geodesic distance");check(!m.add(40.01,-3,5,14000,14000,"cycling"),"jump filtered");check(m.meters==distance,"jump not accumulated");check(!m.add(40.0002,-3,100,16000,16000,"cycling"),"poor accuracy filtered");check(!m.add(40.0002,-3,5,11000,16000,"cycling"),"out of order filtered");check(!m.add(40.0002,-3,5,13000,40000,"cycling"),"stale fix filtered");check(!m.add(Double.NaN,-3,5,20000,20000,"cycling"),"NaN filtered");m.resetAnchor();m.add(41,-3,5,25000,25000,"cycling");check(m.meters==distance,"pause does not bridge route");m.add(42,-3,5,60000,60000,"cycling");check(m.meters==distance,"long gap does not bridge route");SportMath24 walk=new SportMath24();walk.add(40,-3,5,10000,10000,"walking");check(!walk.add(40.0002,-3,5,12000,12000,"walking"),"walking speed cap");SportMath24 stationary=new SportMath24();stationary.add(40,-3,10,10000,10000,"cycling");stationary.add(40.000001,-3,10,12000,12000,"cycling");check(stationary.meters==0,"GPS jitter ignored");System.out.println("PASS SportMath24: distance, accuracy, stale/order, jumps, sport limits, pause/gap anchors, jitter");}
}
